from fractions import Fraction

Matrix = list[list[int | float | Fraction]]


def _shape(m: Matrix) -> tuple[int, int]:
    """Return (rows, cols) of m, raising ValueError if it is empty or ragged."""
    if not m or any(not row for row in m):
        raise ValueError("matrix must be non-empty with non-empty rows")
    width = len(m[0])
    if any(len(row) != width for row in m):
        raise ValueError("matrix rows must all have the same length")
    return len(m), width


def transpose(m: Matrix) -> Matrix:
    rows, cols = _shape(m)
    return [[m[i][j] for i in range(rows)] for j in range(cols)]


def matmul(a: Matrix, b: Matrix) -> Matrix:
    rows_a, cols_a = _shape(a)
    rows_b, cols_b = _shape(b)
    if cols_a != rows_b:
        raise ValueError(f"shape mismatch: {rows_a}x{cols_a} @ {rows_b}x{cols_b}")
    return [
        [sum(a[i][k] * b[k][j] for k in range(cols_a)) for j in range(cols_b)]
        for i in range(rows_a)
    ]


def identity(n: int) -> Matrix:
    if n < 1:
        raise ValueError("identity size must be at least 1")
    return [[1 if i == j else 0 for j in range(n)] for i in range(n)]


def _det_gauss(m: Matrix, convert) -> int | float | Fraction:
    """Gaussian elimination with partial pivoting; `convert` sets the number type."""
    n = len(m)
    work = [[convert(x) for x in row] for row in m]
    sign = 1
    det = convert(1)
    for k in range(n):
        pivot = max(range(k, n), key=lambda r: abs(work[r][k]))
        if work[pivot][k] == 0:
            return convert(0)
        if pivot != k:
            work[k], work[pivot] = work[pivot], work[k]
            sign = -sign
        p = work[k][k]
        det *= p
        for r in range(k + 1, n):
            f = work[r][k] / p
            for j in range(k, n):
                work[r][j] -= f * work[k][j]
    return sign * det


def determinant(m: Matrix) -> int | float | Fraction:
    rows, cols = _shape(m)
    if rows != cols:
        raise ValueError(f"determinant requires a squa

re matrix, got {rows}x{cols}")
    if any(isinstance(x, float) for row in m for x in row):
        return _det_gauss(m, float)
    det = _det_gauss(m, Fraction)
    if all(isinstance(x, int) for row in m for x in row):
        return int(det)
    return det

