def leibniz_det(m):
    """Reference determinant via permutation expansion, independent of the module."""
    n = len(m)
    total = 0
    for perm in itertools.permutations(range(n)):
        sign = 1
        for i in range(n):
            for j in range(i + 1, n):
                if perm[i] > perm[j]:
                    sign = -sign
        term = sign
        for i in range(n):
            term = term * m[i][perm[i]]
        total += term
    return total


